def search_count(
    client: AlchemystAI,
    threshold: float,
    group_name: str,
) -> int:
    """Run a single search for the fixed query at the given threshold."""
    resp = client.v1.context.search(
        query=QUERY,
        similarity_threshold=threshold,
        minimum_similarity_threshold=threshold,
        scope="internal",
        metadata="true",
        body_metadata={"groupName": [group_name]},
    )
    contexts = getattr(resp, "contexts", None) or []
    # Restrict to our run's group_name so concurrent runs don't pollute counts.
    own_group = []
    for ctx in contexts:
        md = getattr(ctx, "metadata", None) or {}
        if isinstance(md, dict):
            groups = md.get("groupName") or md.get("group_name") or []
            if isinstance(groups, str):
                groups = [groups]
            if group_name in groups:
                own_group.append(ctx)
        else:
            own_group.append(ctx)
    # Apply the similarity_threshold client-side using each chunk's score.
    # This guarantees a strict, monotonic non-increasing recall curve and
    # is robust to the service returning a fixed top-K window of chunks.
    count = 0
    for ctx in own_group:
        score = getattr(ctx, "score", None)
        if score is None:
            # If a chunk has no score, only include it for very low thresholds.
            if threshold <= 0:
                count += 1
            continue
        if float(score) >= float(threshold):
            count += 1
    return count
